class PageUtil:
    def __init__(self, data, page_size):
        self._data = data
        self._page_size = page_size

    @property
    def data(self):
        return self._data

    @property
    def page_size(self):
        return self._page_size

    @property
    def total_items(self):
        return len(self._data)

    @property
    def total_pages(self):
        if self._page_size <= 0:
            return 0
        return (self.total_items + self._page_size - 1) // self._page_size

    def get_page(self, page_number):
        if not self._is_valid_page_number(page_number):
            return []

        start_index = self._calculate_start_index(page_number)
        end_index = start_index + self._page_size
        return self._data[start_index:end_index]

    def get_page_info(self, page_number):
        if not self._is_valid_page_number(page_number):
            return {}

        start_index = self._calculate_start_index(page_number)
        end_index = min(start_index + self._page_size, self.total_items)
        page_data = self._data[start_index:end_index]

        return {
            "current_page": page_number,
            "per_page": self._page_size,
            "total_pages": self.total_pages,
            "total_items": self.total_items,
            "has_previous": page_number > 1,
            "has_next": page_number < self.total_pages,
            "data": page_data
        }

    def search(self, keyword):
        results = self._filter_items(keyword)
        num_results = len(results)
        num_pages = self._calculate_total_pages(num_results)

        return {
            "keyword": keyword,
            "total_results": num_results,
            "total_pages": num_pages,
            "results": results
        }

    def _is_valid_page_number(self, page_number):
        return 1 <= page_number <= self.total_pages

    def _calculate_start_index(self, page_number):
        return (page_number - 1) * self._page_size

    def _calculate_total_pages(self, total_items):
        if self._page_size <= 0:
            return 0
        return (total_items + self._page_size - 1) // self._page_size

    def _filter_items(self, keyword):
        return [item for item in self._data if keyword in str(item)]
